const safeRead = key => {try { return localStorage.getItem(key); } catch { return null; }};
const safeWrite = (key,value) => {try {localStorage.setItem(key,value);} catch {}};
function setLanguage(lang){if(!['en','ru'].includes(lang))lang='en';document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const copy=translations[el.dataset.i18n];if(copy)el.innerHTML=copy[lang];});document.querySelectorAll('[data-lang]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.lang===lang)));document.title=location.pathname.includes('szczyrk')?(lang==='ru'?'Шчирк · Зима в Польше · Travels':'Szczyrk · Winter in Poland · Travels'):location.pathname.includes('cerny-dul')?(lang==='ru'?'Černý Důl · Зима в Чехии · Travels':'Černý Důl · Winter in Czechia · Travels'):location.pathname.includes('solden')?(lang==='ru'?'Сёльден · Зимняя поездка · Travels':'Sölden · Winter escape · Travels'):(lang==='ru'?'Travels · Путешествия по сезонам':'Travels · Seasonal journeys');safeWrite('travels-language',lang);}
setLanguage(safeRead('travels-language')||'en');document.querySelectorAll('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>setLanguage(btn.dataset.lang)));
document.querySelectorAll('[data-check]').forEach(input=>{input.checked=safeRead(input.dataset.check)==='true';input.addEventListener('change',()=>safeWrite(input.dataset.check,String(input.checked)));});
const sectionLinks=[...document.querySelectorAll('.nav a')];function updateSection(){let current=sectionLinks[0];for(const link of sectionLinks){const target=document.querySelector(link.getAttribute('href'));if(target&&target.getBoundingClientRect().top<180)current=link;}sectionLinks.forEach(link=>{link.classList.toggle('active',link===current);if(link===current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}window.addEventListener('scroll',updateSection,{passive:true});updateSection();

document.querySelectorAll("[data-piste-toggle]").forEach(btn=>btn.addEventListener("click",()=>{const on=btn.getAttribute("aria-pressed")!=="true";btn.setAttribute("aria-pressed",String(on));document.querySelectorAll("[data-piste-layer]").forEach(layer=>{if(layer.dataset.pisteLayer===btn.dataset.pisteToggle)layer.style.display=on?"":"none";});}));
